python - <<'PY'
from PIL import Image
import numpy as np
for c in ['front','left','right','topview']:
 im=np.asarray(Image.open('/app/output/initial_'+c+'.png'))
 d=np.load('/app/output/initial_depth_'+c+'.npy').squeeze()
 print('\n',c)
 for y in range(0,240,8):
  row=[]
  for x in range(0,320,8):
   r,g,b=im[y,x]
   if r>90 and r>g*1.25 and r>b*1.25: continue # robot red
   if (r<100 and g<100 and b<120) or (r>90 and 25<g<120 and 20<b<100):
    if y>80 and y<180: row.append((x,y,tuple(im[y,x]),round(float(d[y,x]),3)))
  if row: print(row[:15])
PY

